// intake.handoverCard.save / .submit — E2 AC1, AC7 (SOP-DEL-01 §3, §5 steps 2–3, §6). Generated by
// `pnpm gen:command`; guard cases kept, acceptance cases added. Submit is tested here with the card it needs.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, runAsOwner, type TestDatabase } from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  grantOf,
  NotFound,
  openTestKernel,
  RuleViolation,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { saveHandoverCard } from '../commands/save-handover-card.ts';
import { submitHandoverCard } from '../commands/submit-handover-card.ts';
import { itemCodes } from '../rules/handover-checklist.ts';

const sales = aStaffActor({ roles: ['sales'] });
const pm = aStaffActor({ roles: ['pm'] });
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
const rows = (from: string, params: unknown[] = []) => countRows(testDb.url, from, params);

/** Every §6 item provided; group F only as "recorded in the restricted notes" (no value). */
const allItems = (except: string[] = []) =>
  itemCodes
    .filter((c) => !except.includes(c))
    .map((code) =>
      code.startsWith('F')
        ? { code, status: 'provided' as const }
        : { code, status: 'provided' as const, value: `${code} in the project folder` },
    );
const content = { identification: { projectName: 'Mall A counting', projectType: 'new' as const } };
const draft = { siteId: '', content, items: allItems(), installsOrConfigures: true, newClientOrPlace: true };
const save = (input: Record<string, unknown> = {}) =>
  t.kernel.execute(saveHandoverCard, sales, { ...draft, siteId: siteA, ...input }, 'test');
const submit = () => t.kernel.execute(submitHandoverCard, sales, { siteId: siteA }, 'test');

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(sales, saveHandoverCard.permission, submitHandoverCard.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('intake.handoverCard.save', () => {
  it('is for Sales and the director; refuses others, an unknown project and bad input, recording nothing', async () => {
    expect(grantOf(saveHandoverCard.permission)?.roles).toEqual(['director', 'sales']);
    const asPm = t.kernel.execute(saveHandoverCard, pm, { ...draft, siteId: siteA }, 'test');
    await expect(asPm).rejects.toBeInstanceOf(Forbidden);
    await expect(save({ siteId: randomUUID() })).rejects.toBeInstanceOf(NotFound);
    for (const bad of [
      { items: [{ code: 'A1', status: 'na', naReason: ' ' }] }, // N/A needs a reason (Annex B)
      { items: [{ code: 'Z9', status: 'provided' }] },
      { content: {} }, // §3 needs the project type
      { content: { ...content, internal: { secret: 'x' } } }, // strict card: nothing outside Annex B
    ]) {
      await expect(save(bad)).rejects.toBeInstanceOf(ValidationFailed);
    }
    expect(await rows('audit_event WHERE command = $1', [saveHandoverCard.name])).toBe(0);
  });

  it('AC7: group F text is refused on the card — it belongs in the restricted notes', async () => {
    const items = [...allItems(['F1']), { code: 'F1', status: 'provided', value: 'promised a free month' }];
    await expect(save({ items })).rejects.toBeInstanceOf(ValidationFailed);
  });

  it('saves a draft with its §3 package and items; saving again updates the same version', async () => {
    const first = await save({ items: allItems(['A2', 'C6']) });
    expect(first).toMatchObject({ version: 1, package: 'full', packageReason: 'new is always Full' });
    expect(await rows(`handover_item WHERE card_id = $1 AND archived_at IS NULL`, [first.id])).toBe(
      itemCodes.length - 2,
    );
    const again = await save({ items: allItems(['A2', 'C6', 'G1']) });
    expect([again.id, again.version]).toEqual([first.id, 1]);
    expect(await rows(`handover_item WHERE card_id = $1 AND archived_at IS NOT NULL`, [first.id])).toBe(1);
  });
});

describe('intake.handoverCard.submit', () => {
  it('is refused while a §6 item is missing or a "Yes" item is N/A, naming them', async () => {
    const err = await submit().catch((e: unknown) => e);
    expect(err).toBeInstanceOf(RuleViolation);
    expect((err as Error).message).toMatch(/SOP-DEL-01 §6.*A2, C6, G1/);
    await save({ items: [...allItems(['A1']), { code: 'A1', status: 'na', naReason: 'no contract yet' }] });
    await expect(submit()).rejects.toThrow(/A1 \(N\/A not allowed\)/);
  });

  it('submits a complete package once; then it is under review and cannot change', async () => {
    await save({ items: [...allItems(['C6']), { code: 'C6', status: 'na', naReason: 'no POC was run' }] });
    const r = await submit();
    expect(r.version).toBe(1);
    expect(await rows(`handover_card WHERE id = $1 AND status = 'submitted'`, [r.id])).toBe(1);
    expect(await rows(`outbox WHERE event_type = 'intake.handoverCard.submitted'`)).toBe(1);
    await expect(save()).rejects.toBeInstanceOf(Conflict);
    await expect(submit()).rejects.toBeInstanceOf(NotFound);
  });

  it('after a return, the next save starts version 2', async () => {
    await runAsOwner(testDb.url, `UPDATE handover_card SET status = 'returned' WHERE site_id = $1`, [siteA]);
    expect((await save()).version).toBe(2);
  });
});
